"""Verify generated bytes, source bindings and marketplace destinations."""
from __future__ import annotations

import json
import hashlib
import re
from pathlib import Path

from .catalog import load_packages, surface_skills
from .render import digest, render_marketplaces, source_binding
from .resources import PRIVATE_NAMES

NATIVE_CHECKS = ('installation', 'mcp_round_trip', 'startup', 'resume', 'clear', 'compact',
                 'preference_off', 'owned_routing', 'manual_invocation', 'superpowers', 'update', 'migration')
PERSONAL_HOME_PATH = re.compile(r'(?<![\w./:-])/(?:Users|home)/[A-Za-z0-9._-]+/')


def native_binding(destination: Path) -> dict:
    """Bind behavior inputs; source/inventory bookkeeping and human root docs are checked separately."""
    included = {'skills', 'runtime', 'hooks', 'server', '.claude-plugin', '.codex-plugin', '.mcp.json'}
    files = {p.relative_to(destination).as_posix(): digest(p) for p in sorted(destination.rglob('*'))
            if p.is_file() and not p.is_symlink() and '__pycache__' not in p.parts
            and p.relative_to(destination).parts[0] in included}
    return {'sha256': hashlib.sha256(json.dumps(files, sort_keys=True).encode()).hexdigest(),
            'resource_count': len(files)}


def verify_acceptance(repo_root: Path, payload: dict) -> list[str]:
    """Reject status-only acceptance and stale behavior resources before a release transition."""
    root = repo_root.resolve()
    evidence_root = root / 'docs/validation/skill-plugins'
    errors = []
    try:
        packages = load_packages(root)
    except (OSError, ValueError, KeyError) as error:
        return [f'Invalid source for native acceptance: {error}']
    def evidence(items, label):
        if not isinstance(items, list) or not items:
            errors.append(f'{label}: missing recorded evidence'); return []
        values = []
        for item in items:
            try:
                path = evidence_root / item['path']
                if path.is_symlink() or not path.resolve().is_relative_to(evidence_root) or digest(path) != item['sha256']:
                    raise ValueError('Evidence path/hash mismatch')
                values.append(json.loads(path.read_text()))
            except (OSError, ValueError, KeyError, TypeError) as error:
                errors.append(f'{label}: invalid recorded evidence: {error}')
        return values
    security = payload.get('production_security', {})
    audits = evidence(security.get('evidence'), 'production security')
    if (security.get('status') != 'verified' or not audits
            or any(a.get('metadata', {}).get('vulnerabilities', {}).get('total') != 0 for a in audits)):
        errors.append('Production security is not verified with a zero-finding audit')
    for surface in ['claude', 'codex']:
        label = f'{surface}-cli'
        record = payload.get('surfaces', {}).get(label, {})
        expected = {p['name']: native_binding(root / 'plugins' / surface / p['name']) for p in packages}
        if record.get('status') != 'verified':
            errors.append(f'{label}: native acceptance is not verified')
        if record.get('artifact_bindings') != expected:
            errors.append(f'{label}: native artifact binding is absent or stale')
        for check in NATIVE_CHECKS:
            if record.get('checks', {}).get(check) != 'verified':
                errors.append(f'{label}: {check} is not verified')
        observed = evidence(record.get('evidence'), label)
        if observed and not any(o.get('surface') == label and o.get('artifact_bindings') == expected
                                and all(o.get('checks', {}).get(c) == 'verified' for c in NATIVE_CHECKS)
                                for o in observed):
            errors.append(f'{label}: recorded evidence does not confirm the bound native checks')
    return errors


def verify_release(repo_root: Path, contracts: dict) -> list[str]:
    """Return artifact errors; this does not certify host behavior or dependency security."""
    root = repo_root.resolve()
    try:
        packages = load_packages(root)
    except (OSError, ValueError, KeyError) as error:
        return [f'Invalid package source: {error}']
    errors = []
    for surface in ['claude', 'codex']:
        for package in packages:
            destination = root / 'plugins' / surface / package['name']
            label = f"{surface}/{package['name']}"
            try:
                for ancestor in [destination, *destination.parents]:
                    if ancestor == root:
                        break
                    if ancestor.is_symlink():
                        raise ValueError('Package directory or parent is a symlink')
                expected_source = source_binding(root, package, contracts)
                if json.loads((destination / '.source.json').read_text()) != expected_source:
                    errors.append(f'{label}: source binding is stale')
                if (destination / 'plugin.json').exists():
                    errors.append(f'{label}: root manifest shadows the approved native format')
                manifest = json.loads((destination / f'.{surface}-plugin/plugin.json').read_text())
                if manifest.get('name') != package['name'] or manifest.get('version') != package['version']:
                    errors.append(f'{label}: manifest name/version does not match source')
                actual_skills = {p.parent.name for p in (destination / 'skills').glob('*/SKILL.md')}
                if actual_skills != set(surface_skills(package, surface)):
                    errors.append(f'{label}: skill membership mismatch {sorted(actual_skills)}')
                inventory = json.loads((destination / '.generated-files.json').read_text())['files']
                actual = {}
                for path in destination.rglob('*'):
                    relative = path.relative_to(destination).as_posix()
                    if path.is_symlink():
                        errors.append(f'{label}: symlink {relative}'); continue
                    if (path.is_file() and '__pycache__' in path.relative_to(destination).parts
                            and path.suffix == '.pyc'):
                        continue
                    if not path.is_file() or relative == '.generated-files.json':
                        continue
                    if path.name in PRIVATE_NAMES or path.name.startswith('.env'):
                        errors.append(f'{label}: private config {relative}')
                    if path.suffix in {'.md', '.json', '.js', '.py', '.sh', '.yaml', '.mjs'}:
                        text = path.read_text(encoding='utf-8', errors='replace')
                        if str(root) in text or (
                            'node_modules' not in path.parts and PERSONAL_HOME_PATH.search(text)
                        ):
                            errors.append(f'{label}: personal absolute path in {relative}')
                        if path.suffix == '.md' and 'node_modules' not in path.parts:
                            prose = re.sub(r'^```.*?^```[^\n]*$', '', text, flags=re.M | re.S)
                            prose = re.sub(r'`+[^`\n]*`+', '', prose)
                            for link in re.findall(r'\[[^\]]+\]\(([^\s)]+)\)', prose):
                                link = link.split('#')[0]
                                if not link or '://' in link or link.startswith(('mailto:', '<')):
                                    continue
                                target = path.parent / link
                                if not target.resolve().is_relative_to(destination) or not target.exists():
                                    errors.append(f'{label}: missing or external local reference {relative}: {link}')
                    actual[relative] = {'sha256': digest(path), 'mode': path.stat().st_mode & 0o777}
                for path in sorted(set(inventory) | set(actual)):
                    if inventory.get(path) != actual.get(path):
                        errors.append(f'{label}: missing, changed or unexpected resource {path}')
            except (OSError, ValueError, KeyError) as error:
                errors.append(f'{label}: incomplete package: {error}')
    try:
        expected_claude, expected_codex = render_marketplaces(root, packages)
        for path, expected in [('.claude-plugin/marketplace.json', expected_claude),
                               ('.agents/plugins/marketplace.json', expected_codex)]:
            if json.loads((root / path).read_text()) != expected:
                errors.append(f'{path}: marketplace does not match package sources')
        for p in expected_claude['plugins']:
            if p['name'] in {package['name'] for package in packages} and not (root / p['source']).is_dir():
                errors.append(f"Missing marketplace source: {p['source']}")
    except (OSError, ValueError, KeyError) as error:
        errors.append(f'Invalid marketplace: {error}')
    return errors
